const s = $('Recibir del principal').first().json;
const entrada = s.Entrada, salida = s.Salida;
const email = String(s.Email || '').toLowerCase();

// Junta las filas de todas las páginas y verifica que la respuesta sea válida
const leer = (nombreNodo) => {
  const paginas = $(nombreNodo).all();
  const filas = [];
  for (const p of paginas) {
    if (!Array.isArray(p.json.results)) {
      throw new Error('RESPUESTA_INESPERADA: "' + nombreNodo + '" no devolvio la lista results');
    }
    filas.push(...p.json.results);
  }
  if (paginas.length && paginas[paginas.length - 1].json.next) {
    throw new Error('PAGINACION_INCOMPLETA: "' + nombreNodo + '" supero el maximo de paginas');
  }
  return filas;
};

const habitaciones = leer('Consultar habitaciones');
const reservas = leer('Consultar reservas').filter(r => r.Estado === 'Confirmada');
const numerosDelTipo = habitaciones.map(h => String(h.Numero));
const base = { habitaciones_revisadas: habitaciones.length, reservas_revisadas: reservas.length };

// 1) ¿Ya existe esta misma reserva? (mismo email, mismas fechas, habitación de este tipo)
const existente = reservas.find(r =>
  String(r.Email || '').toLowerCase() === email &&
  r.Entrada === entrada && r.Salida === salida &&
  numerosDelTipo.includes(String(r.Habitacion)));
if (existente) {
  return [{ json: { ...base, disponible: false, duplicada: true, motivo: 'RESERVA_DUPLICADA',
    habitacion: String(existente.Habitacion), reserva_existente_id: existente.id } }];
}

// 2) Una habitación está ocupada si una reserva confirmada se cruza con las fechas pedidas
const ocupada = (numero) => reservas.some(r =>
  String(r.Habitacion) === numero && r.Entrada < salida && r.Salida > entrada);

// 3) Primera habitación libre, ordenadas por número
const libre = habitaciones
  .sort((a, b) => String(a.Numero).localeCompare(String(b.Numero), undefined, { numeric: true }))
  .find(h => !ocupada(String(h.Numero)));

return [{ json: { ...base, disponible: !!libre, duplicada: false,
  motivo: libre ? 'DISPONIBLE' : 'SIN_DISPONIBILIDAD',
  habitacion: libre ? String(libre.Numero) : null, reserva_existente_id: null } }];
